package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	Role     string `json:"role"`
	DeptCode string `json:"dept_code"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput performs basic length check and trims whitespace
func sanitizeInput(input string) string {
	input = strings.TrimSpace(input)
	if len(input) > 200 {
		input = input[:200]
	}
	return input
}

// buildSearchQuery constructs a dynamic search query based on filters
func buildSearchQuery(name, dept, role string) string {
	base := "SELECT id, name, email, role, dept_code FROM employees WHERE active = true"
	clauses := []string{}

	if name != "" {
		// Using ILIKE for case-insensitive partial match
		clauses = append(clauses, fmt.Sprintf("name ILIKE '%%%s%%'", name))
	}
	if dept != "" {
		clauses = append(clauses, fmt.Sprintf("dept_code = '%s'", dept))
	}
	if role != "" {
		clauses = append(clauses, fmt.Sprintf("role = '%s'", role))
	}

	if len(clauses) > 0 {
		base += " AND " + strings.Join(clauses, " AND ")
	}
	base += " ORDER BY name LIMIT 50"
	return base
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	// Extract and sanitize parameters
	name := sanitizeInput(r.URL.Query().Get("name"))
	dept := sanitizeInput(r.URL.Query().Get("dept"))
	role := sanitizeInput(r.URL.Query().Get("role"))

	// Log search for audit
	log.Printf("Search request: name=%q dept=%q role=%q from=%s",
		name, dept, role, r.RemoteAddr)

	query := buildSearchQuery(name, dept, role)
	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	results := []SearchResult{}
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.Role, &sr.DeptCode); err != nil {
			log.Printf("Scan error: %v", err)
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/employees/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
